mapper.select:
select date_format(default_date, '%Y-%m-%d') as stat_date, count(*) as debt_default_count, ifnull(sum(default_exposure_amount), 0) as default_exposure_amount from corporate_debt_default where deleted_flag = 0 and default_date between #{startDate} and #{endDate}
and default_level = #{defaultLevel}
group by default_date order by default_date

select date_format(latest_default_date, '%Y-%m-%d') as stat_date, count(*) as customer_default_count from corporate_customer_default where deleted_flag = 0 and latest_default_date between #{startDate} and #{endDate}
and highest_default_level = #{defaultLevel}
group by latest_default_date order by latest_default_date

select date_format(o.overdue_date, '%Y-%m-%d') as stat_date, count(*) as overdue_count, max(o.overdue_days) as max_overdue_days, ifnull(sum(o.total_overdue_amount), 0) as overdue_amount from corporate_credit_overdue o where o.deleted_flag = 0 and o.overdue_date between #{startDate} and #{endDate}
and exists ( select 1 from corporate_debt_default d where d.debt_no = o.debt_no and d.deleted_flag = 0 and d.default_level = #{defaultLevel} )
group by o.overdue_date order by o.overdue_date

select default_level, count(*) as debt_default_count, ifnull(sum(default_exposure_amount), 0) as default_exposure_amount, ifnull(sum(loss_amount), 0) as loss_amount from corporate_debt_default where deleted_flag = 0 and default_date between #{startDate} and #{endDate}
and default_level = #{defaultLevel}
group by default_level order by case default_level when 'A' then 1 when 'B' then 2 when 'C' then 3 else 9 end

select debt_default_no, date_format(default_date, '%Y-%m-%d') as default_date, customer_no, customer_name_snapshot, contract_no, debt_no, default_level, overdue_days, ifnull(five_category, '') as five_category, ifnull(rating_result, '') as rating_result, default_exposure_amount, loss_amount, ifnull(default_reason, '') as default_reason, default_status from corporate_debt_default where deleted_flag = 0 and default_date between #{startDate} and #{endDate}
and default_level = #{defaultLevel}
order by default_date desc, id desc limit #{limit}
